// Package security holds the cluster PKI, TLS configuration and join tokens
// (ADRs 0004 and 0007).
//
// One CA, generated by the server on first start, signs:
//   - the server certificate (DNS name ServerName, server auth only);
//   - client certificates, whose subject carries the identity: CN is the
//     name, O is the role (RoleNode, RoleAdmin, or RoleBuilder). A builder
//     certificate also carries its repository scope in OU (ADR 0021).
package security

import (
	"crypto"
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/sha256"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/hex"
	"encoding/pem"
	"errors"
	"fmt"
	"math/big"
	"net"
	"os"
	"path/filepath"
	"time"
)

const (
	// ServerName is the only DNS name in the server certificate. Clients
	// always verify against it, whatever address they dial, so the server
	// certificate doesn't depend on IPs or NAT. This is safe because the CA
	// is private to the cluster and issues no other server certificates.
	ServerName = "shoal-server"

	RoleNode    = "shoal:node"
	RoleAdmin   = "shoal:admin"
	RoleBuilder = "shoal:builder"

	// Certificates are backdated to tolerate clock skew between machines.
	clockSkew = 5 * time.Minute

	CAValidity     = 10 * 365 * 24 * time.Hour
	ServerValidity = 365 * 24 * time.Hour
	AdminValidity  = 365 * 24 * time.Hour
	NodeValidity   = 30 * 24 * time.Hour

	// BuildCertificateValidity is the life of a builder's push certificate
	// (ADR 0021, pass B). It covers the longest build, which is killed
	// before this runs out, plus the push. The registry also refuses a
	// builder whose Build has finished, so a leaked certificate is useless
	// after the run.
	BuildCertificateValidity = 2 * time.Hour
)

// Identity is who a client certificate belongs to. Scope is set for builder
// certificates only: the one registry repository the builder may push to.
// It is carried in the certificate's organizational unit.
type Identity struct {
	Name  string
	Role  string
	Scope string
}

func (id Identity) String() string { return id.Role + "/" + id.Name }

// NewKey generates an ECDSA P-256 private key.
func NewKey() (*ecdsa.PrivateKey, error) {
	k, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, fmt.Errorf("generate key: %w", err)
	}
	return k, nil
}

// CA signs cluster certificates.
type CA struct {
	Cert *x509.Certificate
	Key  crypto.Signer
}

// LoadOrCreateCA loads ca.crt and ca.key from dir, creating them on first
// use. created reports whether a new CA was generated.
func LoadOrCreateCA(dir string, now time.Time) (ca *CA, created bool, err error) {
	certPath, keyPath := filepath.Join(dir, "ca.crt"), filepath.Join(dir, "ca.key")
	certPEM, certErr := os.ReadFile(certPath)
	keyPEM, keyErr := os.ReadFile(keyPath)
	switch {
	case certErr == nil && keyErr == nil:
		cert, err := ParseCertPEM(certPEM)
		if err != nil {
			return nil, false, fmt.Errorf("load CA certificate %s: %w", certPath, err)
		}
		key, err := ParseKeyPEM(keyPEM)
		if err != nil {
			return nil, false, fmt.Errorf("load CA key %s: %w", keyPath, err)
		}
		return &CA{Cert: cert, Key: key}, false, nil
	case !errors.Is(certErr, os.ErrNotExist) || !errors.Is(keyErr, os.ErrNotExist):
		return nil, false, fmt.Errorf("CA in %s is incomplete or unreadable (cert: %v, key: %v)", dir, certErr, keyErr)
	}

	key, err := NewKey()
	if err != nil {
		return nil, false, err
	}
	tmpl := &x509.Certificate{
		Subject:               pkix.Name{CommonName: "shoal cluster CA"},
		NotBefore:             now.Add(-clockSkew),
		NotAfter:              now.Add(CAValidity),
		KeyUsage:              x509.KeyUsageCertSign | x509.KeyUsageCRLSign | x509.KeyUsageDigitalSignature,
		BasicConstraintsValid: true,
		IsCA:                  true,
		MaxPathLenZero:        true,
	}
	if tmpl.SerialNumber, err = serial(); err != nil {
		return nil, false, err
	}
	der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, key.Public(), key)
	if err != nil {
		return nil, false, fmt.Errorf("create CA certificate: %w", err)
	}
	cert, err := x509.ParseCertificate(der)
	if err != nil {
		return nil, false, fmt.Errorf("parse CA certificate: %w", err)
	}
	keyOut, err := EncodeKeyPEM(key)
	if err != nil {
		return nil, false, err
	}
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return nil, false, fmt.Errorf("create PKI dir: %w", err)
	}
	// Key first: a crash in between leaves no certificate without its key.
	if err := WriteFileAtomic(keyPath, keyOut, 0o600); err != nil {
		return nil, false, err
	}
	if err := WriteFileAtomic(certPath, EncodeCertPEM(cert), 0o644); err != nil {
		return nil, false, err
	}
	return &CA{Cert: cert, Key: key}, true, nil
}

// IssueServer issues the server certificate for pub.
func (ca *CA) IssueServer(pub crypto.PublicKey, now time.Time) (*x509.Certificate, error) {
	return ca.issue(&x509.Certificate{
		Subject:     pkix.Name{CommonName: ServerName},
		DNSNames:    []string{ServerName},
		ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
	}, pub, now, ServerValidity)
}

// IssueServerFor issues a server certificate for other names and addresses
// (e.g. the web portal, which browsers reach by IP or host name).
func (ca *CA) IssueServerFor(pub crypto.PublicKey, now time.Time, dnsNames []string, ips []net.IP) (*x509.Certificate, error) {
	return ca.issue(&x509.Certificate{
		Subject:     pkix.Name{CommonName: "shoal portal"},
		DNSNames:    dnsNames,
		IPAddresses: ips,
		ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
	}, pub, now, ServerValidity)
}

// IssueClient issues a client certificate for id.
func (ca *CA) IssueClient(pub crypto.PublicKey, id Identity, now time.Time, validity time.Duration) (*x509.Certificate, error) {
	if id.Name == "" || (id.Role != RoleNode && id.Role != RoleAdmin) {
		return nil, fmt.Errorf("invalid identity %q", id)
	}
	return ca.issue(&x509.Certificate{
		Subject:     pkix.Name{CommonName: id.Name, Organization: []string{id.Role}},
		ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth},
	}, pub, now, validity)
}

// IssueBuilder issues a push certificate for one Build. id.Name is the
// Build, id.Scope the repository it may push to. The organizational unit
// carries the scope, so the registry reads it from the certificate alone.
func (ca *CA) IssueBuilder(pub crypto.PublicKey, id Identity, now time.Time, validity time.Duration) (*x509.Certificate, error) {
	if id.Name == "" || id.Scope == "" {
		return nil, fmt.Errorf("invalid builder identity %q", id)
	}
	return ca.issue(&x509.Certificate{
		Subject:     pkix.Name{CommonName: id.Name, Organization: []string{RoleBuilder}, OrganizationalUnit: []string{id.Scope}},
		ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth},
	}, pub, now, validity)
}

// SignBuilderCSR issues a builder push certificate for id with the public key
// of a DER-encoded certificate request. As with SignCSR, the request's
// subject is ignored.
func (ca *CA) SignBuilderCSR(der []byte, id Identity, now time.Time, validity time.Duration) (*x509.Certificate, error) {
	csr, err := x509.ParseCertificateRequest(der)
	if err != nil {
		return nil, fmt.Errorf("parse certificate request: %w", err)
	}
	if err := csr.CheckSignature(); err != nil {
		return nil, fmt.Errorf("certificate request signature: %w", err)
	}
	return ca.IssueBuilder(csr.PublicKey, id, now, validity)
}

// SignCSR issues a client certificate for id with the public key of a
// DER-encoded certificate request. The request's subject is ignored: the
// identity is always decided by the caller.
func (ca *CA) SignCSR(der []byte, id Identity, now time.Time, validity time.Duration) (*x509.Certificate, error) {
	csr, err := x509.ParseCertificateRequest(der)
	if err != nil {
		return nil, fmt.Errorf("parse certificate request: %w", err)
	}
	if err := csr.CheckSignature(); err != nil {
		return nil, fmt.Errorf("certificate request signature: %w", err)
	}
	return ca.IssueClient(csr.PublicKey, id, now, validity)
}

func (ca *CA) issue(tmpl *x509.Certificate, pub crypto.PublicKey, now time.Time, validity time.Duration) (*x509.Certificate, error) {
	var err error
	if tmpl.SerialNumber, err = serial(); err != nil {
		return nil, err
	}
	tmpl.NotBefore = now.Add(-clockSkew)
	tmpl.NotAfter = now.Add(validity)
	tmpl.KeyUsage = x509.KeyUsageDigitalSignature
	der, err := x509.CreateCertificate(rand.Reader, tmpl, ca.Cert, pub, ca.Key)
	if err != nil {
		return nil, fmt.Errorf("issue certificate for %s: %w", tmpl.Subject.CommonName, err)
	}
	return x509.ParseCertificate(der)
}

// IdentityFromCert extracts the identity of a verified client certificate.
func IdentityFromCert(c *x509.Certificate) (Identity, error) {
	if c.Subject.CommonName == "" || len(c.Subject.Organization) != 1 {
		return Identity{}, errors.New("certificate has no shoal identity")
	}
	id := Identity{Name: c.Subject.CommonName, Role: c.Subject.Organization[0]}
	switch id.Role {
	case RoleNode, RoleAdmin:
	case RoleBuilder:
		// A builder certificate without a scope would allow nothing useful;
		// refuse it rather than read it as unscoped.
		if len(c.Subject.OrganizationalUnit) != 1 || c.Subject.OrganizationalUnit[0] == "" {
			return Identity{}, errors.New("builder certificate has no repository scope")
		}
		id.Scope = c.Subject.OrganizationalUnit[0]
	default:
		return Identity{}, fmt.Errorf("certificate has unknown role %q", id.Role)
	}
	return id, nil
}

// CAHash returns "sha256:<hex>" of the certificate's public key, the value
// agents pin with --ca-hash.
func CAHash(c *x509.Certificate) string {
	sum := sha256.Sum256(c.RawSubjectPublicKeyInfo)
	return "sha256:" + hex.EncodeToString(sum[:])
}

// NewCSR returns a DER-encoded certificate request for key.
func NewCSR(key crypto.Signer, name string) ([]byte, error) {
	der, err := x509.CreateCertificateRequest(rand.Reader, &x509.CertificateRequest{Subject: pkix.Name{CommonName: name}}, key)
	if err != nil {
		return nil, fmt.Errorf("create certificate request: %w", err)
	}
	return der, nil
}

func serial() (*big.Int, error) {
	n, err := rand.Int(rand.Reader, new(big.Int).Lsh(big.NewInt(1), 127))
	if err != nil {
		return nil, fmt.Errorf("generate serial number: %w", err)
	}
	return n, nil
}

// EncodeCertPEM encodes a certificate as PEM.
func EncodeCertPEM(c *x509.Certificate) []byte {
	return pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: c.Raw})
}

// EncodeKeyPEM encodes a private key as PKCS #8 PEM.
func EncodeKeyPEM(key crypto.Signer) ([]byte, error) {
	der, err := x509.MarshalPKCS8PrivateKey(key)
	if err != nil {
		return nil, fmt.Errorf("encode private key: %w", err)
	}
	return pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: der}), nil
}

// ParseCertPEM parses the first certificate in PEM data.
func ParseCertPEM(data []byte) (*x509.Certificate, error) {
	b, _ := pem.Decode(data)
	if b == nil || b.Type != "CERTIFICATE" {
		return nil, errors.New("no PEM certificate found")
	}
	return x509.ParseCertificate(b.Bytes)
}

// ParseKeyPEM parses a PKCS #8 PEM private key.
func ParseKeyPEM(data []byte) (crypto.Signer, error) {
	b, _ := pem.Decode(data)
	if b == nil || b.Type != "PRIVATE KEY" {
		return nil, errors.New("no PEM private key found")
	}
	k, err := x509.ParsePKCS8PrivateKey(b.Bytes)
	if err != nil {
		return nil, fmt.Errorf("parse private key: %w", err)
	}
	s, ok := k.(crypto.Signer)
	if !ok {
		return nil, fmt.Errorf("unsupported private key type %T", k)
	}
	return s, nil
}

// WriteFileAtomic writes data to a temporary file and renames it over path,
// so readers never see a partial file.
func WriteFileAtomic(path string, data []byte, perm os.FileMode) error {
	tmp, err := os.CreateTemp(filepath.Dir(path), "."+filepath.Base(path)+".tmp*")
	if err != nil {
		return fmt.Errorf("write %s: %w", path, err)
	}
	defer os.Remove(tmp.Name()) // no-op after a successful rename
	if err := tmp.Chmod(perm); err != nil {
		tmp.Close()
		return fmt.Errorf("write %s: %w", path, err)
	}
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return fmt.Errorf("write %s: %w", path, err)
	}
	if err := tmp.Sync(); err != nil {
		tmp.Close()
		return fmt.Errorf("write %s: %w", path, err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("write %s: %w", path, err)
	}
	if err := os.Rename(tmp.Name(), path); err != nil {
		return fmt.Errorf("write %s: %w", path, err)
	}
	return nil
}
